  /*find an item with the provided barcode,
   *if the item is not exist,
   *create an order entry,
   *and the set the quantity to the provided quantity,
   *and the subamount is the item price multiply the quantity and the order item is the item,
   *and save the order entry and the current order product is contain the order entry*/
  orderItem(barcode: number, quantity: number): boolean {
    /*Definition Start*/
    let item: Item = l({
      logic: () =>
        getRepository(Item).find(
          (o: any) =>
            l({
              logic: () => o.Barcode === barcode,
              description: "o.Barcode=barcode",
            }).build().pass,
        ),
      description: "Item.allInstance()->any(o|o.Barcode=barcode)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(item) === false,
        description: "item.oclIsUndefined()=false",
      }).build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let orderEntry: OrderEntry;
    return l({
      execute: () => (orderEntry = new OrderEntry()),
      description: "orderEntry.oclIsNew()",
    })
      .and({
        execute: () => (orderEntry.Quantity = quantity),
        description: "orderEntry.Quantity=quantity",
      })
      .and({
        execute: () => (orderEntry.SubAmount = item.Price * quantity),
        description: "orderEntry.SubAmount=item.Price*quantity",
      })
      .and({
        execute: () => (orderEntry.Item = item),
        description: "orderEntry.Item=item",
      })
      .and({
        execute: () =>
          this.currentOrderProduct.ContainedEntries.push(orderEntry),
        description:
          "self.currentOrderProduct.ContainedEntries->includes(orderEntry)",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
